const $=id=>document.getElementById(id),files=[null,null];let changes=[],page=0;for(const [i,id] of ['a','b'].entries())$(id).addEventListener('change',async e=>{const f=e.target.files[0];files[i]=null;$('result').hidden=true;$('export').disabled=true;if(!f)return;if(f.size>2*1024*1024){$('message').textContent='Maximum 2 MB per text file.';return;}try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());files[i]=text;$(id+'n').textContent=f.name+' · '+TextCore.lines(text).length+' lines';$('message').textContent='';}catch{$('message').textContent='Only UTF-8 text is supported.';} $('go').disabled=!files.every(x=>x!==null);});$('go').addEventListener('click',()=>{try{changes=TextCore.diff(files[0],files[1],{trim:$('trim').checked,ignoreCase:$('case').checked});page=0;const added=changes.filter(x=>x.kind==='added').length,removed=changes.filter(x=>x.kind==='removed').length;$('summary').textContent=added+' added · '+removed+' removed lines';$('result').hidden=false;$('export').disabled=false;$('message').textContent='';render();}catch(e){$('result').hidden=true;$('message').textContent=e.message;}});function render(){const changed=changes.filter(x=>x.kind!=='same'),pages=Math.max(1,Math.ceil(changed.length/100));page=Math.max(0,Math.min(page,pages-1));$('rows').replaceChildren();for(const r of changed.slice(page*100,page*100+100)){const tr=document.createElement('tr');for(const v of [r.old??'—',r.new??'—',r.kind,r.text]){const td=document.createElement('td');td.textContent=v;tr.append(td);}tr.className=r.kind;$('rows').append(tr);}$('count').textContent=changed.length+' changed lines';$('page').textContent=(page+1)+' / '+pages;$('prev').disabled=page===0;$('next').disabled=page===pages-1;}$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};$('export').onclick=()=>{const report=changes.filter(x=>x.kind!=='same').map(x=>(x.kind==='added'?'+':'-')+' '+x.text).join('\n');const url=URL.createObjectURL(new Blob([report],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='text-diff.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};